    cols_8 = [x for x in range(len(grid[r])) if grid[r][x] == 8]
    if not cols_8:
        return 0

    min_c, max_c = min(cols_8), max(cols_8)
    span = max_c - min_c + 1

    # Row-relative position
    if span <= 1:
        return 1  # single cell
    else:
        rel_c = (c - min_c) / (span - 1)

    # Thresholds for 3 zones
    if rel_c < 1/3:
        return 3
    elif rel_c < 2/3:
        return 1
    else:
        return 4

